"""Text-to-SQL harness: draft policy call + execution check + one repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy calls capped per task: env.max_calls
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'([^']*)'")
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _tables(schema):
    return re.findall(r'CREATE TABLE\s+[`"\[]?([A-Za-z_][A-Za-z_0-9]*)', schema or "", re.I)


def _sample_values(env, schema, sql, limit=3):
    """Fetch a few real values for columns referenced near string literals in the draft."""
    lits = [m for m in LITERAL.findall(sql) if m.strip()]
    if not lits:
        return ""
    # candidate identifiers appearing in the query (columns / tables / aliases)
    idents = set(IDENT.findall(sql))
    notes = []
    seen = set()
    for tbl in _tables(schema):
        if tbl not in idents:
            continue
        info = env.execute(f'PRAGMA table_info("{tbl}")', max_rows=100)
        if not info.get("ok"):
            continue
        cols = [r[1] for r in info.get("rows", []) if len(r) > 1]
        for col in cols:
            if col not in idents or (tbl, col) in seen:
                continue
            # only probe columns plausibly related to a literal (text-ish names or any col cheaply)
            res = env.execute(
                f'SELECT DISTINCT "{col}" FROM "{tbl}" WHERE "{col}" IS NOT NULL LIMIT 8',
                max_rows=8,
            )
            if not res.get("ok") or not res.get("rows"):
                continue
            vals = [str(r[0]) for r in res["rows"]]
            joined = " | ".join(v[:60] for v in vals)
            # keep note if some literal roughly relates to these values, else keep short anyway
            related = any(
                lit.lower() in v.lower() or v.lower() in lit.lower() or lit.lower().split()[0] in v.lower()
                for lit in lits for v in vals if lit.split()
            )
            if related or len(notes) < limit:
                notes.append(f"{tbl}.{col} sample values: {joined}")
                seen.add((tbl, col))
        if len(notes) >= limit + 2:
            break
    return "\n".join(notes[: limit + 2])


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\nColumn descriptions:\n{desc.strip()[:2000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    # Execution check: repair once if the draft errors or returns no rows.
    try:
        res = env.execute(sql, max_rows=5)
    except Exception:
        res = {"ok": False, "error": "execution failed", "n_rows": 0}

    needs_repair = (not res.get("ok")) or res.get("n_rows", 0) == 0
    if needs_repair:
        if not res.get("ok"):
            feedback = f"The query failed with error: {res.get('error')}. Fix the SQL so it runs."
        else:
            feedback = (
                "The query executed but returned 0 rows. That usually means a filter value does not "
                "match the stored data (spelling, spacing, wrong column) or a join/subtraction is wrong. "
                "Re-examine the filter columns and values; use LIKE '%...%' substring matching for text "
                "containment, and check the sample values below."
            )
            samples = ""
            try:
                samples = _sample_values(env, schema, sql)
            except Exception:
                samples = ""
            if samples:
                feedback += "\nActual stored values:\n" + samples
        feedback += (
            "\nAlso re-check the projection: if the question asks about whole entities without naming "
            "attributes, select the full rows of the main table (T1.*). "
            "Return the corrected query in a single ```sql block."
        )
        messages.append({"role": "assistant", "content": reply})
        messages.append({"role": "user", "content": feedback})
        try:
            reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
            sql2 = extract_sql(reply2)
            if sql2:
                res2 = env.execute(sql2, max_rows=5)
                # accept the repair unless it is broken while the original at least ran
                if res2.get("ok") or not res.get("ok"):
                    sql = sql2
        except Exception:
            pass

    return {"sql": sql}

